def parsear_duracion(s):
    duracion = s.split('h')
    total_minutos = 0
    for duracion_segundo in duracion[1:]:
        if 'm' in duracion_segundo:
            duracion_segundo = duracion_segundo.split('m')[0]
            minutos = int(duracion_segundo.split('h')[0]) * 60 + int(duracion_segundo.split('h')[1].split('m')[0])
            total_minutos += minutos
        elif 's' in duracion_segundo:
            duracion_segundo = duracion_segundo.split('s')[0]
            total_minutos += int(duracion_segundo.split('h')[0]) * 60 + int(duracion_segundo.split('m')[0])
    return total_minutos

