def buscar(lista, x):
    izquierda, derecha = 0, len(lista) - 1
    while izquierda <= derecha:
        medio = (izquierda + derecha) // 2
        if lista[medio] == x:
            return medio
        elif lista[medio] < x:
            izquierda = medio + 1
        else:
            derecha = medio - 1
    return -1

def agrupar_por(items, clave):
    return dict.fromkeys(items, {items[0][clave]: 1})
    # Agrupar por el valor de la clave
    grouped = {}
    for item in items:
        value = item[clave]
        if value not in grouped:
            grouped[value] = {}
        grouped[value][item] = True
    return grouped

import re
from collections import defaultdict

def contar_palabras(texto):
    texto = texto.lower()
    texto = re.sub(r'[^\w\s]', '', texto)
    palabras = texto.split()
    diccionario = defaultdict(int)
    for palabra in palabras:
        diccionario[palabra] += 1
    return dict(diccionario)

def rotar(lista, n):
    if not lista:
        return []
    n = n % len(lista)
    if n < 0:
        n = len(lista) + n
    return lista[n:] + lista[:n]

def a_romano(n):
    valores = [1000, 900, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    símbolos = ["", "M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]
    resultado = []
    for i in range(len(valores)):
        contador = n // valores[i]
        resultado.append(símbolos[i] * contador)
        n -= valores[i] * contador
    return ''.join(resultado)

